function sec_datetime_local($utc){if(!$utc)return '';try{$date=new DateTimeImmutable($utc,new DateTimeZone('UTC'));if(function_exists('wbce_timezone')){$zone=wbce_timezone();if($zone instanceof DateTimeZone)$date=$date->setTimezone($zone);}return $date->format('Y-m-d\TH:i');}catch(Throwable $e){return '';}}
