<section><h3>Neue Ausnahme, dauerhafte Sperre oder Filterregel</h3><form method="post" class="sec-rule-form"><input type="hidden" name="sc_page" value="rules"><input type="hidden" name="action" value="rule_add"><?php echo $admin->getFTAN();?><label>Regelart<select name="kind" data-rule-kind><?php foreach($types as $key=>$meta)echo '<option value="'.$key.'">'.sec_h($meta[0]).'</option>';?></select></label><label data-rule-value-label>IP-Adresse<input name="pattern" required placeholder="192.0.2.10" data-rule-value></label><label>Notiz<input name="note" placeholder="Optional"></label><div class="sec-rule-help" data-rule-help></div><button>Regel hinzufügen</button></form><script type="application/json" data-rule-config><?php echo json_encode($types,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);?></script></section>

